/// <reference types="node" />

import { mkdtempSync, rmSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { randomUUID as mockRandomUUID } from 'node:crypto';
import { Alert } from 'react-native';
import { act, cleanup, fireEvent, renderRouter, screen, testRouter } from 'expo-router/testing-library';
import RootLayout from '../app/_layout';
import type { TemplateContent } from '../src/models/workout';
import { createExerciseCatalogService } from '../src/services/exercise-catalog-service';
import { createLocalDatabase } from '../src/services/local-database';
import { createSqliteWorkoutService } from '../src/services/sqlite-workout-service';
import { namedDisplayStore } from '../test-support/local-router';

jest.mock('expo-crypto', () => ({ randomUUID: () => mockRandomUUID() }));

jest.mock('expo-sqlite', () => ({
  openDatabaseAsync: (name: string) => mockOpenDatabase(name),
}));

// Jest replaces the native bridge. SQL still runs against a real, disposable database file.
const { DatabaseSync } = process.getBuiltinModule('node:sqlite') as typeof import('node:sqlite');
let directory: string;
let connections: InstanceType<typeof DatabaseSync>[];

beforeEach(() => {
  directory = mkdtempSync(join(tmpdir(), 'openfit-sqlite-'));
  connections = [];
});

afterEach(async () => {
  await cleanup();
  jest.restoreAllMocks();
  for (const connection of connections) connection.close();
  rmSync(directory, { recursive: true, force: true });
});

async function mockOpenDatabase(name: string, loseSaveResponse?: () => boolean) {
  const db = new DatabaseSync(join(directory, name));
  connections.push(db);
  return {
    async execAsync(sql: string) {
      db.exec(sql);
      if (sql === 'COMMIT' && loseSaveResponse?.()) throw new Error('Save response lost after commit');
    },
    async getAllAsync<T>(sql: string, ...params: (string | number)[]) {
      return db.prepare(sql).all(...params) as T[];
    },
    async getFirstAsync<T>(sql: string, ...params: (string | number)[]) {
      return (db.prepare(sql).get(...params) as T | undefined) ?? null;
    },
    async runAsync(sql: string, ...params: (string | number)[]) { db.prepare(sql).run(...params); },
    async closeAsync() { db.close(); connections.splice(connections.indexOf(db), 1); },
  };
}

function service(loseSaveResponse?: () => boolean) {
  return createSqliteWorkoutService(createLocalDatabase(() => mockOpenDatabase('training.db', loseSaveResponse)), mockRandomUUID);
}

test('requires a local name, then saves and reopens a template with the bundled catalog and no fetch', async () => {
  const fetch = jest.spyOn(globalThis, 'fetch').mockRejectedValue(new Error('Offline'));
  await renderRouter('./app', { initialUrl: '/workouts' });
  const name = await screen.findByLabelText('Display name');
  expect(screen.getByText('Training data is stored on this device. Backup is unavailable.')).toBeVisible();
  expect(screen.queryByRole('button', { name: /^Workouts, tab/ })).toBeNull();
  await fireEvent.changeText(name, '   ');
  await fireEvent.press(screen.getByRole('button', { name: 'Continue' }));
  expect(screen.getByRole('alert')).toHaveTextContent('Enter a display name.');

  await fireEvent.changeText(name, '  Alex  ');
  await fireEvent.press(screen.getByRole('button', { name: 'Continue' }));
  expect(await screen.findByText('Hi, Alex!')).toBeVisible();
  expect(await screen.findByText('No templates yet.')).toBeVisible();
  await startDraft('Offline plan');
  await fireEvent.press(screen.getByRole('button', { name: 'Add exercise' }));
  await fireEvent.changeText(await screen.findByRole('search', { name: 'Search exercises' }), 'Barbell bench press');
  await fireEvent.press(screen.getByRole('button', { name: /^View Barbell Bench Press\./ }));
  expect(screen.getByRole('image', { name: 'Barbell Bench Press — Start image' })).toBeVisible();
  await fireEvent.press(screen.getByRole('button', { name: 'Next image' }));
  expect(screen.getByRole('image', { name: 'Barbell Bench Press — Peak image' })).toBeVisible();
  await fireEvent.press(screen.getByRole('button', { name: 'Add to template' }));
  await fireEvent.press(screen.getByRole('button', { name: 'Sets for exercise 1' }));
  await fireEvent.changeText(screen.getByLabelText('Exercise 1 set 1 weight (lb)'), '25');
  await fireEvent.changeText(screen.getByLabelText('Exercise 1 set 1 reps'), '8');
  await fireEvent.press(screen.getByRole('button', { name: 'Done' }));
  await fireEvent.press(screen.getByRole('button', { name: 'Save' }));
  await screen.findByRole('button', { name: 'Edit template details' });
  await fireEvent.press(screen.getByRole('button', { name: /^Workouts, tab/ }));
  expect(await screen.findByText('Sample workout history')).toBeVisible();

  await cleanup();
  for (const connection of connections.splice(0)) connection.close();
  const app = await renderRouter('./app');
  expect(await screen.findByText('Hi, Alex!')).toBeVisible();
  expect(app.getPathname()).toBe('/templates');
  await fireEvent.press(await screen.findByRole('button', { name: /^Offline plan/ }));
  await fireEvent.press(await screen.findByRole('button', { name: 'Edit template details' }));
  await fireEvent.changeText(screen.getByLabelText('Template title'), 'Revised plan');
  await fireEvent.press(screen.getByRole('button', { name: 'Save' }));
  expect(await screen.findByText('Revised plan')).toBeVisible();
  const alert = jest.spyOn(Alert, 'alert').mockImplementation(() => {});
  await fireEvent.press(screen.getByRole('button', { name: 'Delete template' }));
  await act(async () => alert.mock.lastCall?.[2]?.find(button => button.text === 'Delete')?.onPress?.());
  expect(await screen.findByText('No templates yet.')).toBeVisible();
  expect(fetch).not.toHaveBeenCalled();
});

test('an earlier SQLite database keeps its template through onboarding, a rename, and relaunch', async () => {
  const previous = new DatabaseSync(join(directory, 'open-fit.db'));
  try {
    previous.exec(`
      CREATE TABLE workout_templates (
        sequence INTEGER PRIMARY KEY, id TEXT NOT NULL UNIQUE, created_at TEXT NOT NULL, content TEXT NOT NULL
      );
      CREATE TABLE template_save_receipts (operation_id TEXT PRIMARY KEY NOT NULL, template_id TEXT NOT NULL, content TEXT NOT NULL);
      CREATE INDEX template_creation_receipts_template ON template_save_receipts (template_id);
      PRAGMA user_version = 2;
    `);
# Local onboarding and SQLite verification

[#141](https://github.com/open-source-fitness/open-fit/issues/141) switches the
production app to local display-name onboarding and uses SQLite for workout
templates. The app ships the RepDB catalog and flat illustrations. Workout
history still shows labeled samples.

## Verified in the worktree

- On Node 24.12.0, `npm ci`, `npm run typecheck`, `npm test` (109 tests in 22
  suites), and `npx expo-doctor` (20 checks) passed.
- The Expo Router tests start the default app with a fresh database and use
  Node's SQLite engine with the Expo SQLite bridge substituted. With JavaScript
  fetch disabled, the tests require a nonblank display name, show the device
  storage and backup notice, greet the user on Templates, inspect both poses of a
  bundled exercise, and save a template. They close the database, remount the
  app, reopen the template, edit it, and delete it.
- A pre-cutover SQLite schema version 2 fixture retains its saved template and
  set targets after migration. A name edited in Settings and the Dark
  appearance both survive an app remount. The remaining SQLite and router
  tests cover draft navigation, cancellation, reordering, snapshots, rollback,
  save retries, and sample history.
- Both iOS and Android Expo exports passed with the Supabase environment
  variables unset, dotenv loading disabled, and Expo offline mode enabled.
  Each bundle contains the local SQLite composition and RepDB instructions.
  Both export manifests reference all 1,203 RepDB illustrations, totaling
  19,804,900 bytes before application packaging. The Hermes bundles measure
  5,327,488 bytes for iOS and 5,317,600 for Android. Source maps contain no
  Supabase runtime or legacy account routes.

The archived account behavior remains in the repository for #142.
`auth-navigation.test.tsx`, `auth-sessions.test.tsx`, and
`production-template-access.test.tsx` exercise the retired router and are
excluded from the active Jest and TypeScript checks. Hosted backend tooling is
tracked by #143.

## Physical-device evidence pending

No iOS or Android device was available. Neither platform ran an installed build
during this verification. The native Expo SQLite bridge, first launch and
catalog rendering in airplane mode, force-close recovery, in-place app update,
and installed package size remain unverified. The database migration and
restart checks above ran through Jest. Follow the
[device-review steps](setup.md#device-review) to complete the offline
template-parity gate.
import {
  DarkTheme,
  DefaultTheme,
  ThemeProvider as NavigationThemeProvider,
} from 'expo-router/react-navigation';
import { Stack } from 'expo-router';
import { StatusBar } from 'expo-status-bar';
import { ActivityIndicator } from 'react-native';
import { SafeAreaView } from 'react-native-safe-area-context';
import { useState } from 'react';
import type { DisplayNameStore } from '../src/services/display-name-store';
import { bundledExerciseCatalogService, type ExerciseCatalogService } from '../src/services/exercise-catalog-service';
import { createNativeServices } from '../src/services/native-services';
import { themePreferenceStore } from '../src/services/theme-preference-store';
import type { WorkoutService } from '../src/services/workout-service';
import { DisplayNameProvider, useDisplayName } from '../src/viewmodels/display-name';
import { ExerciseCatalogProvider } from '../src/viewmodels/exercise-catalog';
import { ThemeProvider, useTheme } from '../src/viewmodels/theme';
import { WorkoutProvider } from '../src/viewmodels/workout-provider';
import { Button, FormError } from '../src/views/ui';

export default function RootLayout({
  catalogService = bundledExerciseCatalogService, displayNameStore, workoutServiceFactory,
}: {
  catalogService?: ExerciseCatalogService;
  displayNameStore?: DisplayNameStore;
  workoutServiceFactory?: () => WorkoutService;
} = {}) {
  const [services] = useState(() => {
    const native = createNativeServices();
    return {
      displayNameStore: displayNameStore ?? native.displayNameStore,
      workoutService: workoutServiceFactory?.() ?? native.workoutService,
    };
  });

  return (
    <ThemeProvider store={themePreferenceStore}>
      <DisplayNameProvider store={services.displayNameStore}>
        <WorkoutProvider service={services.workoutService}>
          <ExerciseCatalogProvider service={catalogService}>
            <Navigation />
          </ExerciseCatalogProvider>
        </WorkoutProvider>
      </DisplayNameProvider>
    </ThemeProvider>
  );
}

function Navigation() {
  const { scheme, colors, ready } = useTheme();
  const { displayName, status, retry } = useDisplayName();
  const base = scheme === 'dark' ? DarkTheme : DefaultTheme;
  return (
    <NavigationThemeProvider
      value={{
        ...base,
        colors: {
          ...base.colors,
          primary: colors.text,
          background: colors.background,
          card: colors.surface,
          text: colors.text,
          border: colors.border,
          notification: colors.accent,
        },
      }}
    >
      <StatusBar style={scheme === 'dark' ? 'light' : 'dark'} />
      {ready && status === 'ready' ? (
        <Stack screenOptions={{ headerShown: false }}>
          <Stack.Screen name="index" />
          <Stack.Protected guard={displayName === null}>
            <Stack.Screen name="onboarding" options={{ headerShown: true, title: 'Welcome' }} />
          </Stack.Protected>
          <Stack.Protected guard={displayName !== null}>
            <Stack.Screen name="(tabs)" />
          </Stack.Protected>
        </Stack>
      ) : (
        <SafeAreaView style={{ flex: 1, justifyContent: 'center', padding: 24, gap: 16, backgroundColor: colors.background }}>
          {status === 'error' ? <>
            <FormError message="Your local data couldn’t be opened. Please try again." />
            <Button label="Try again" onPress={retry} />
          </> : <ActivityIndicator accessibilityLabel="Loading your settings" color={colors.text} />}
        </SafeAreaView>
      )}
    </NavigationThemeProvider>
  );
}
import { randomUUID } from 'expo-crypto';
import { openDatabaseAsync } from 'expo-sqlite';
import { createDisplayNameStore } from './display-name-store';
import { createLocalDatabase } from './local-database';
import { createSqliteWorkoutService } from './sqlite-workout-service';

export function createNativeServices(databaseName = 'open-fit.db') {
  const database = createLocalDatabase(() => openDatabaseAsync(databaseName, { useNewConnection: true }));
  return {
    displayNameStore: createDisplayNameStore(database),
    workoutService: createSqliteWorkoutService(database, randomUUID),
  };
}

