import { createContext, useCallback, useContext, useRef, useState, type SetStateAction, type PropsWithChildren } from 'react';
import type { TemplateContent, WorkoutTemplate } from '../models/workout';
import type { TemplateDraft } from './template-editor';
import type { TemplateSaveContext, WorkoutService } from '../services/workout-service';

interface WorkoutContextValue {
  drafts: Readonly<Record<string, TemplateDraft>>;
  setDraft(id: string, update: SetStateAction<TemplateDraft | null>): void;
  nextPlacementId(): string;
  service: WorkoutService;
  templatesVersion: number;
  savingTemplate: boolean;
  hasUnsavedChanges: boolean;
  setDraftDirty(id: string, dirty: boolean): void;
  deleteTemplate(id: string): Promise<void>;
  saveTemplate(id: string | null, details: TemplateContent): Promise<WorkoutTemplate>;
}

const WorkoutContext = createContext<WorkoutContextValue | null>(null);

export function WorkoutProvider({ service, children }: PropsWithChildren<{ service: WorkoutService }>) {
  const [draftRecords, setDraftRecords] = useState<Record<string, { content: TemplateDraft; context: TemplateSaveContext }>>({});
  const drafts = Object.fromEntries(Object.entries(draftRecords).map(([id, draft]) => [id, draft.content]));
  const placementNumber = useRef(0);
  const nextPlacementId = useCallback(() => `placement-${++placementNumber.current}`, []);
  const [dirtyDrafts, setDirtyDrafts] = useState<Readonly<Record<string, boolean>>>({});
  const setDraftDirty = useCallback((id: string, dirty: boolean) => {
    setDirtyDrafts((current) => current[id] === dirty ? current : { ...current, [id]: dirty });
  }, []);
  const setDraft = useCallback((id: string, update: SetStateAction<TemplateDraft | null>) => {
    setDraftRecords((current) => {
      const draft = typeof update === 'function' ? update(current[id]?.content ?? null) : update;
      const next = { ...current };
      if (draft) next[id] = { content: draft, context: current[id]?.context ?? {} };
      else delete next[id];
      return next;
    });
  }, []);
  const [templatesVersion, setTemplatesVersion] = useState(0);
  const [savingTemplate, setSavingTemplate] = useState(false);
  const saving = useRef(false);
  const mutate = useCallback(async <T,>(operation: () => Promise<T>) => {
    if (saving.current) throw new Error('A template change is already pending.');
    saving.current = true;
    setSavingTemplate(true);
    try {
      const result = await operation();
      setTemplatesVersion((value) => value + 1);
      return result;
    } finally {
      saving.current = false;
      setSavingTemplate(false);
    }
  }, []);
  const saveTemplate = useCallback((id: string | null, content: TemplateContent) =>
    mutate(() => id === null ? service.createTemplate(content, draftRecords.new?.context)
      : service.updateTemplate(id, content, draftRecords[id]?.context)), [mutate, service, draftRecords]);
  const deleteTemplate = useCallback((id: string) => mutate(() => service.deleteTemplate(id)), [mutate, service]);
  return (
    <WorkoutContext.Provider value={{ drafts, setDraft, nextPlacementId, service, templatesVersion, savingTemplate, saveTemplate, deleteTemplate,
      setDraftDirty, hasUnsavedChanges: Object.values(dirtyDrafts).some(Boolean) }}>
      {children}
    </WorkoutContext.Provider>
  );
}

export function useWorkouts() {
  const value = useContext(WorkoutContext);
  if (!value) throw new Error('WorkoutProvider is required.');
  return value;
}
import { useEffect, useRef, useState, type SetStateAction } from 'react';
import { createTemplateExercise, validateTemplate, type TemplateContent } from '../models/workout';
import type { CatalogExercise } from '../models/exercise';
import { useWorkouts } from './workout-provider';
import { useTemplateViewModel } from './workouts';

export interface TemplateDraft {
  title: string;
  description: string;
  exercises: readonly (Omit<TemplateContent['exercises'][number], 'sets'> & {
    readonly sets: readonly { weight: string; reps: string }[];
  })[];
}

function toDraft(template: TemplateContent): TemplateDraft {
  return { ...template, exercises: template.exercises.map((exercise) => ({ ...exercise,
    sets: exercise.sets.map((set) => ({ weight: String(set.targetWeight), reps: String(set.targetReps) })),
  })) };
}

function toContent(draft: TemplateDraft): TemplateContent {
  return validateTemplate({ ...draft, exercises: draft.exercises.map((exercise) => ({ ...exercise,
    sets: exercise.sets.map((set, index) => ({ setNumber: index + 1,
      targetWeight: set.weight.trim() === '' ? NaN : Number(set.weight),
      targetReps: set.reps.trim() === '' ? NaN : Number(set.reps),
    })),
  })) });
}

export function useTemplateEditorViewModel(id: string) {
  const isNew = id === 'new';
  const resource = useTemplateViewModel(isNew ? null : id);
  const { savingTemplate, saveTemplate, deleteTemplate, setDraft: updateDraft, setDraftDirty } = useWorkouts();
  const draftEditor = useTemplateDraftViewModel(id);
  const { draft } = draftEditor;
  const setDraft = (update: SetStateAction<TemplateDraft | null>) => updateDraft(id, update);
  const [deleted, setDeleted] = useState(false);
  const [createdId, setCreatedId] = useState<string | null>(null);
  useEffect(() => {
    if (isNew) updateDraft(id, (current) => current ?? { title: '', description: '', exercises: [] });
    return () => updateDraft(id, null);
  }, [id, isNew, updateDraft]);
  const [error, setError] = useState<string | null>(null);
  const saving = useRef(false);
  const template = resource.state.status === 'ready' ? resource.state.data : null;

  function startEditing() {
    if (!template || saving.current) return;
    setDraft(toDraft(template));
    setError(null);
  }
  function cancelEditing() {
    if (saving.current) return;
    setDraft(null);
    setError(null);
  }
  async function save() {
    if (!draft || saving.current || savingTemplate) return;
    let content: TemplateContent;
    try { content = toContent(draft); }
    catch (cause) {
      setError(cause instanceof Error ? cause.message : 'Check your template.');
      return;
    }
    saving.current = true;
    setError(null);
    try {
      const saved = await saveTemplate(isNew ? null : id, content);
      setDraft(null);
      if (isNew) setCreatedId(saved.id);
    } catch {
      setError('Your changes couldn’t be saved. Please try again.');
    } finally { saving.current = false; }
  }
  async function removeTemplate() {
    if (saving.current || savingTemplate || draft || isNew) return;
    saving.current = true;
    setError(null);
    try {
      await deleteTemplate(id);
      setDeleted(true);
    } catch { setError('This template couldn’t be deleted. Please try again.'); }
    finally { saving.current = false; }
  }
  const baseline = isNew ? { title: '', description: '', exercises: [] } : template ? toDraft(template) : null;
  const dirty = !!draft && !!baseline && JSON.stringify(draft) !== JSON.stringify(baseline);
  useEffect(() => { setDraftDirty(id, dirty); return () => setDraftDirty(id, false); }, [id, dirty, setDraftDirty]);
  return { ...resource, id, deleted, removeTemplate, createdId, error, dirty,
    ...draftEditor, startEditing, cancelEditing, save };
}

// A catalog route can add only to a still-open draft identified by its owner route.
export function useTemplateCatalogSelection(draftId: string | undefined) {
  const { drafts, setDraft, nextPlacementId, savingTemplate } = useWorkouts();
  const available = !!draftId && !!drafts[draftId] && !savingTemplate;
  function add(exercise: CatalogExercise) {
    if (!available || !draftId) return false;
    const placementId = nextPlacementId();
    setDraft(draftId, (draft) => {
      if (!draft) return draft;
      const placement = createTemplateExercise(placementId, exercise, []);
      return { ...draft, exercises: [...draft.exercises, { ...placement, sets: [{ weight: '', reps: '' }] }] };
    });
    return true;
  }
  return { available, add };
}

